demo.program:
// TPM presence demo (simulated model)
var tpm={version:'2.0',pcrs:24,ek:true};
console.log('TPM '+tpm.version+': '+tpm.pcrs+' PCRs, EK '+(tpm.ek?'present':'absent'));
console.log('root of trust available');

// PCR extend demo (simulated model)
function h(s){var x=0x811c9dc5;for(var i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,0x01000193);}return('0000000'+(x>>>0).toString(16)).slice(-8);}
var pcr='00000000';
var comps=['firmware','bootloader','kernel'];
for(var i=0;i<comps.length;i++){pcr=h(pcr+comps[i]);console.log(comps[i]+' -> '+pcr);}
console.log('boot measured into PCR');

// Boot chain demo (simulated model)
var chain=[['firmware',true],['bootloader',true],['kernel',false]];
for(var i=0;i<chain.length;i++){console.log(chain[i][0]+': '+(chain[i][1]?'signed OK':'UNSIGNED - halt'));if(!chain[i][1])break;}
console.log('secure boot enforced');

// Attestation demo (simulated model)
function h(s){var x=7;for(var i=0;i<s.length;i++){x=(x*33+s.charCodeAt(i))>>>0;}return x.toString(16);}
var quote=h('pcr-values|nonce-123');
console.log('attestation quote: '+quote+' (EK-chained)');
console.log('verifier: boot state proven');

// Sealed storage demo (simulated model)
var sealed={data:'disk-key',pcr:'a1b2c3d4'};
var current='a1b2c3d4';
console.log('unseal: '+(sealed.pcr===current?'SUCCESS':'DENIED'));
console.log('bound to PCR state');

// Key hierarchy demo (simulated model)
var tree={EK:['SRK'],SRK:['sign-key','enc-key']};
for(var k in tree){console.log(k+' wraps: '+tree[k].join(','));}
console.log('hierarchy: delete SRK, children gone');

// HSM demo (simulated model)
var hsm={model:'Luna-class',fips:'140-3 L3',keys:1000};
console.log('HSM '+hsm.fips+': '+hsm.keys+' keys in tamper HW');
console.log('keys never leave the module');

// FIPS levels demo (simulated model)
var lv={1:'software',2:'tamper-evident',3:'tamper-resistant',4:'active response'};
for(var k in lv){console.log('L'+k+': '+lv[k]);}
console.log('defense buys certified');

// Algorithm demo (simulated model)
var algos=['RSA-2048','ECC-P256','AES-256','SHA-256'];
for(var i=0;i<algos.length;i++){console.log('TPM supports: '+algos[i]);}
console.log('agile crypto menu');

// Disk encryption demo (simulated model)
console.log('boot PCRs match -> key unsealed -> disk unlocks');
console.log('foreign machine: stays encrypted');

// Fleet attestation demo (simulated model)
var nodes=[['n1','good'],['n2','good'],['n3','unknown']];
for(var i=0;i<nodes.length;i++){console.log(nodes[i][0]+': '+(nodes[i][1]==='good'?'admitted':'QUARANTINED'));}
console.log('fleet attested');

// Provisioning demo (simulated model)
console.log('ownership taken: SRK created, auth set');
console.log('TPM bound to owner');

// EAL demo (simulated model)
console.log('EAL4+: methodically tested, reviewed');
console.log('assurance measured');

// Trust chain demo (simulated model)
var c=['silicon','measure','enforce','attest','seal'];
for(var i=0;i<c.length;i++){console.log((i+1)+'. '+c[i]);}
console.log('trust chain complete');

// Ceremony demo (simulated model)
var custodians=3, shares=3;
console.log(custodians+' custodians, '+shares+' shares, quorum 2');
console.log('ceremony complete, key born');
